import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, smoothstep, time } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, DirectionalLight, AmbientLight } = ctx.THREE;

  const group = new Group();
  const timelines = [];

  // 1. Color Palette Definitions
  const colors = {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  // 2. Stage Backdrop (designed to anchor the node in 3D outer bounds)
  const bgGeom = new PlaneGeometry(7, 6);
  const bgMat = new MeshBasicNodeMaterial();

  // Custom TSL Vertical Gradient with subtle grain texture behavior
  const vUv = uv();
  const gradient = mix(
    vec3(0.043, 0.043, 0.062), // Dark near-black base (#0b0b10)
    vec3(0.086, 0.086, 0.114), // Ink (#16161d)
    vUv.y
  );
  bgMat.colorNode = gradient;

  const bgMesh = new Mesh(bgGeom, bgMat);
  bgMesh.position.set(0, 0, -2.5);
  group.add(bgMesh);

  // 3. Engineered Local Lighting for Machined Metal Aesthetics
  const keyLight = new DirectionalLight(colors.paper, 1.2);
  keyLight.position.set(2, 3, 4);
  group.add(keyLight);

  const rimLight = new DirectionalLight(colors.accent, 0.8);
  rimLight.position.set(-2, -3, 2);
  group.add(rimLight);

  // 4. Detailed Base Plate / Label Container
  const plateGeom = new PlaneGeometry(3.0, 1.0);
  const plateMat = new MeshStandardNodeMaterial({
    color: colors.surface,
    metalness: 0.55,
    roughness: 0.5,
    clearcoat: 0.2
  });

  const plate = new Mesh(plateGeom, plateMat);
  group.add(plate);

  // Load brushed-metal texture if available in assets
  const imageUrl = config.imageUrl ?? config.intent?.visualSpec?.imageUrl;
  if (imageUrl) {
    ctx.textureLoader.loadTexture(imageUrl).then((texture) => {
      if (texture) {
        texture.anisotropy = 8;
        plateMat.roughnessMap = texture;
        plateMat.metalnessMap = texture;
        plateMat.needsUpdate = true;
      }
    }).catch(() => {});
  }

  // 5. High-contrast premium typography (Lora display styled)
  // Retrieve target visual specifications or default
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const labelText = items[0]?.text ?? "Collection 2";

  // Create text container
  const textObj = ctx.fontAtlas.createText(labelText, {
    fontSize: 28, // approx scaled headline size
    color: colors.paper,
    align: 'left'
  });

  // Pivot & Position Text inside the Label Card
  textObj.position.set(-1.1, -0.1, 0.02);
  group.add(textObj);

  // 6. Signal red accent graphic element
  const signalRectGeom = new PlaneGeometry(0.06, 0.25);
  const signalRectMat = new MeshBasicNodeMaterial({ color: colors.accent });
  const signalRect = new Mesh(signalRectGeom, signalRectMat);
  signalRect.position.set(-1.3, 0.0, 0.02);
  group.add(signalRect);

  // Decorative border lines for an engineered watch-maker blueprint layout
  const borderGeom = new PlaneGeometry(2.9, 0.01);
  const borderMat = new MeshBasicNodeMaterial({ color: colors.ink });
  const topBorder = new Mesh(borderGeom, borderMat);
  topBorder.position.set(0, 0.45, 0.015);
  const bottomBorder = topBorder.clone();
  bottomBorder.position.set(0, -0.45, 0.015);
  group.add(topBorder, bottomBorder);

  // 7. Dynamic Weighted Entrance Motion
  group.position.y += 0.25;
  group.scale.set(0.95, 0.95, 0.95);

  const entranceTl = gsap.timeline();
  timelines.push(entranceTl);

  entranceTl.to(group.position, {
    y: 0,
    duration: 0.9,
    ease: 'power4.out'
  });

  entranceTl.to(group.scale, {
    x: 1,
    y: 1,
    z: 1,
    duration: 0.9,
    ease: 'power4.out'
  }, 0);

  // Apply primitives specified by the visualSpec configuration
  const activePrimitives = [];
  if (config.cinematicPrimitives) {
    for (const prim of config.cinematicPrimitives) {
      if (ctx.primitives[prim.name]) {
        const result = ctx.primitives[prim.name](group, prim.params);
        if (result) {
          activePrimitives.push(result);
        }
      }
    }
  }

  // Complete cleanup chain
  group.userData = {
    cleanup() {
      timelines.forEach(tl => tl.kill());
      activePrimitives.forEach(p => {
        if (typeof p.cleanup === 'function') p.cleanup();
      });
      // Dispose Geometries and Materials local to this node frame
      bgGeom.dispose();
      bgMat.dispose();
      plateGeom.dispose();
      plateMat.dispose();
      signalRectGeom.dispose();
      signalRectMat.dispose();
      borderGeom.dispose();
      borderMat.dispose();
    }
  };

  return group;
}
